/**
 * Corroboration Signal and Replication Pack PE Types
 *
 * Corroboration signals are automatically generated by system events
 * (escrow completion, promise fulfillment, x402 settlement, etc.)
 * to upgrade PE attestation from 'software' (0.8x) to 'corroborated' (1.1x).
 *
 * Replication packs are agent-generated verifiable work artifacts
 * that qualify for 'software_verified' (0.9x) attestation tier.
 *
 * SECURITY INVARIANT: Never suppress, delay, or filter valid corroboration signals.
 * Invalid signals (missing target_pe_id, unverifiable evidence) should be rejected, not suppressed.
 */

export type CorroborationSignalType =
  | 'on_chain_confirmation'     // Block confirmation of a crypto tx
  | 'merchant_settlement'       // 200 response from proxied payment
  | 'x402_settlement'           // PAYMENT-RESPONSE receipt
  | 'promise_fulfillment'       // Counterparty marks promise done
  | 'job_delivery_accepted'     // Job recipient accepts delivery
  | 'goal_resolution'           // Goal envelope resolves successfully
  | 'escrow_completed'          // Escrow released without dispute
  | 'counterparty_attestation'; // Generic third-party post-attestation

export interface CorroborationSignalPEDetails {
  target_pe_id: string;           // The PE being corroborated
  target_pe_hash: string;         // Hash of target PE for verification
  corroborating_party: string;    // wallet_id or 'system' for auto-signals
  signal_type: CorroborationSignalType;
  evidence_hash: string;          // Hash of the corroborating evidence
  evidence_ref?: string;          // Optional: tx hash, job id, session id, etc.
  automated: boolean;             // true for all system-generated signals
}

export interface ReplicationPackPEDetails {
  action_pe_id: string;           // The action PE this pack verifies
  input_hash: string;             // SHA-256 of inputs
  output_hash: string;            // SHA-256 of outputs
  model_id: string;               // Model identifier
  pack_hash: string;              // SHA-256 of the replication pack contents (matches relay wire field)
  independent_verification_url?: string;  // Where to submit for verification
  pack_version: string;           // Schema version
}
